insert into public.products (slug, data, sort)
values
  ('book-a-sloth', '{"slug":"book-a-sloth","name":"Book A Sloth","color":"#D95D00","tagline":"Easy scheduling. Easier life.","category":"Scheduling SaaS","status":"Beta","url":"https://bookasloth.in","about":"Book A Sloth is a modern appointment booking and scheduling platform built around the idea that time should feel organized, not stressful. Inspired by the calm and deliberate nature of a sloth, it helps businesses, professionals, and service providers manage bookings, collect payments, send reminders, and eliminate scheduling chaos. In a world obsessed with speed, Book A Sloth stands for reliability, certainty, and thoughtful time management — every appointment happens effortlessly, for customers and businesses alike."}'::jsonb, 0),
  ('ticket-dino', '{"slug":"ticket-dino","name":"Ticket Dino","color":"#2BB673","tagline":"Events worth remembering.","category":"Events & Ticketing","status":"Building","about":"Ticket Dino is an event discovery and ticketing ecosystem designed to help organizers create, manage, and sell tickets while giving attendees a seamless way to discover memorable experiences. The dinosaur symbolizes scale, excitement, and experiences that leave a lasting impact. Whether it''s conferences, workshops, concerts, or community events, Ticket Dino transforms event management from a logistical burden into a powerful engine for connection and unforgettable memories."}'::jsonb, 1),
  ('the-parliament', '{"slug":"the-parliament","name":"The Parliament","color":"#2563EB","tagline":"Conversations with purpose.","category":"Community & Discourse","status":"Concept","about":"The Parliament is a digital space built for meaningful conversations, communities, and structured exchange of ideas. Drawing inspiration from democratic institutions where voices shape decisions, the platform encourages thoughtful discourse over noise and collaboration over chaos. It can serve as a hub for communities, organizations, creators, or professionals seeking a place where ideas are debated, shared, and refined with purpose and civility."}'::jsonb, 2),
  ('coffee-and-toffee', '{"slug":"coffee-and-toffee","name":"Coffee & Toffee","color":"#FF2E93","tagline":"Connections that matter.","category":"Social","status":"Concept","about":"Coffee & Toffee is a social platform centered around human connection, companionship, and conversations that matter. The brand evokes the warmth of coffee and the sweetness of toffee — relationships that begin casually and evolve into something meaningful. Whether used for friendships, networking, dating, or shared interests, the platform is designed to create authentic interactions in a digital world often dominated by superficial engagement."}'::jsonb, 3),
  ('link-lantern', '{"slug":"link-lantern","name":"Link Lantern","color":"#A3FF12","tagline":"One link to light the way.","category":"Creator Tools","status":"Building","about":"Link Lantern is a creator-first digital identity platform that helps individuals and businesses consolidate their online presence into a single, powerful destination. Like a lantern guiding travelers through darkness, it illuminates the paths that matter by organizing links, content, and digital assets in one place. It empowers creators, entrepreneurs, and brands to increase discoverability, strengthen personal branding, and turn attention into action."}'::jsonb, 4),
  ('alluminaty', '{"slug":"alluminaty","name":"Alluminaty","color":"#5470C6","tagline":"Networks that outlast graduation.","category":"Alumni & Education","status":"Concept","about":"Alluminaty is an alumni networking and institutional engagement platform built to strengthen lifelong connections between students, graduates, and educational institutions. Graduation isn''t the end of a journey but the beginning of a powerful network of mentorship, collaboration, and opportunity. By connecting alumni communities digitally, Alluminaty helps institutions foster relationships, support career growth, and create ecosystems that keep generating value long after the classroom."}'::jsonb, 5),
  ('whatsloom', '{"slug":"whatsloom","name":"WhatsLoom","color":"#007F5F","tagline":"Conversations, woven into systems.","category":"Messaging & Automation","status":"Building","about":"WhatsLoom is a communication and automation platform designed to transform everyday conversations into scalable business systems. Inspired by a loom weaving individual threads into something larger, it helps businesses automate messaging, nurture leads, manage customer interactions, and build stronger relationships through conversational workflows. It bridges human interaction and automation — letting businesses grow without losing their personal touch."}'::jsonb, 6),
  ('serp-sutra', '{"slug":"serp-sutra","name":"SERP Sutra","color":"#5DA9E9","tagline":"The discipline of search.","category":"SEO Intelligence","status":"Building","about":"SERP Sutra is an SEO intelligence and search optimization platform that combines timeless marketing principles with modern search technology. Borrowing from the idea of ancient sutras as collections of wisdom, it gives marketers, creators, and businesses the insights needed to improve visibility, rankings, and organic growth. SERP Sutra treats search not merely as an algorithmic challenge but as a discipline where strategy, content, and user intent converge for long-term success."}'::jsonb, 7),
  ('marketing-bug', '{"slug":"marketing-bug","name":"Marketing Bug","color":"#C1121F","tagline":"Catch the growth bug.","category":"Newsletter & Community","status":"Live","about":"Marketing Bug is a growth-driven platform and community for marketers, founders, creators, and businesses obsessed with how attention becomes influence and influence becomes growth. The ''bug'' represents a contagious curiosity for experimentation, storytelling, analytics, and performance marketing. Through education, tools, insights, and practical frameworks, Marketing Bug helps people master modern marketing and keep adapting to an ever-evolving digital landscape."}'::jsonb, 8)
insert into public.services (slug, data, sort)
values
  ('seo', '{"slug":"seo","name":"SEO & Organic Growth","icon":"Search","tagline":"Compounding traffic systems","outcome":"Own your category in search — and in the LLMs that are quietly replacing it.","description":"I build SEO as infrastructure: topic clusters, programmatic surfaces, and an answer-first content system engineered to compound for years, not spike for a quarter.","deliverables":["Technical SEO audit and remediation plan","Topic cluster and information architecture","Programmatic SEO build-out where it fits","Schema, internal linking, and GEO/LLM optimisation"],"process":[{"step":"Audit","detail":"Find what''s broken and what''s winnable in 30 days."},{"step":"Architect","detail":"Design the cluster and the compounding mechanism."},{"step":"Build","detail":"Ship the pillar, spokes, and programmatic layer."},{"step":"Compound","detail":"Refresh, expand, and instrument on a fixed cadence."}],"startingAt":"₹1.5L / month"}'::jsonb, 0),
  ('performance', '{"slug":"performance","name":"Performance Marketing","icon":"Target","tagline":"Paid that pays back","outcome":"Profitable acquisition at scale, with a testing system that keeps it that way.","description":"Account structure, creative systems, and a post-click experience that converts. I treat paid as a system you can tune, not a slot machine you feed.","deliverables":["Account restructure around intent tiers","Creative testing system and production cadence","Landing page rebuilds for message-match and speed","Pragmatic attribution your team will actually trust"],"process":[{"step":"Diagnose","detail":"Find the real bottleneck — usually post-click."},{"step":"Restructure","detail":"Clean account, clean testing matrix."},{"step":"Systematise","detail":"Make creative a pipeline, not a scramble."},{"step":"Scale","detail":"Push spend only where the unit economics hold."}],"startingAt":"₹2L / month"}'::jsonb, 1),
  ('content', '{"slug":"content","name":"Content Strategy","icon":"PenLine","tagline":"Editorial that earns trust","outcome":"A content engine that demonstrates thinking and feeds every other channel.","description":"From editorial strategy to a repurposing pipeline that turns one serious idea into a month of distribution. Voice-led, data-anchored, never thin.","deliverables":["Editorial strategy and content pillars","Repurposing pipeline (one idea → twenty assets)","Editorial QA rubric and brand-voice system","Distribution calendar across owned channels"],"process":[{"step":"Strategy","detail":"Pillars tied to business outcomes, not topics."},{"step":"System","detail":"Stand up the production and QA pipeline."},{"step":"Distribute","detail":"Repurpose and place across every surface."},{"step":"Review","detail":"Kill what doesn''t work, double the rest."}],"startingAt":"₹1.25L / month"}'::jsonb, 2),
  ('ai-workflows', '{"slug":"ai-workflows","name":"AI Automation","icon":"Sparkles","tagline":"Leverage at every layer","outcome":"Compress time and expand output by wiring AI into the work that matters.","description":"Custom AI workflows for research, drafting, analysis, and ops — designed so judgement stays human and quality goes up, not down.","deliverables":["Workflow audit and automation roadmap","Prompt libraries trained on your brand and data","Human-in-the-loop pipelines with QA gates","Team enablement and documentation"],"process":[{"step":"Map","detail":"Find the highest-leverage, lowest-risk automations."},{"step":"Build","detail":"Wire the workflow with quality gates."},{"step":"Validate","detail":"Prove quality holds before scaling."},{"step":"Enable","detail":"Hand the team a system they can run."}],"startingAt":"₹1.75L / month"}'::jsonb, 3),
  ('advisory', '{"slug":"advisory","name":"Startup Advisory","icon":"Compass","tagline":"Founder-to-founder","outcome":"Clear thinking on growth, distribution, and product from someone in the arena.","description":"Hands-on advisory for early and growth-stage founders. Distribution-first product thinking, positioning, and the unglamorous systems that compound.","deliverables":["Bi-weekly working sessions","Growth and distribution strategy","Positioning and messaging review","Async access for fast decisions"],"process":[{"step":"Context","detail":"Understand the business and the real constraints."},{"step":"Focus","detail":"Identify the one lever that matters this quarter."},{"step":"Execute","detail":"Work the lever together, week over week."},{"step":"Compound","detail":"Build the system so it outlasts the engagement."}],"startingAt":"₹75K / month"}'::jsonb, 4),
  ('speaking', '{"slug":"speaking","name":"Speaking & Workshops","icon":"Mic","tagline":"Talks with receipts","outcome":"Sessions that leave a room with systems they can use on Monday.","description":"Keynotes and workshops on SEO, AI workflows, and founder-led growth — built on real experiments and outcomes, not recycled theory.","deliverables":["Keynote or workshop tailored to your audience","Practical frameworks and takeaway templates","Q&A and follow-up resources","Optional recording and repurposing rights"],"process":[{"step":"Brief","detail":"Understand the audience and the outcome."},{"step":"Craft","detail":"Build a session around real receipts."},{"step":"Deliver","detail":"Engage the room, leave them with systems."},{"step":"Extend","detail":"Provide resources that outlast the talk."}],"startingAt":"On request"}'::jsonb, 5)
