values
  (null, '{"quote":"Shubham brings rare clarity. His strategies are grounded, actionable, and built for scale.","name":"Sri","role":"Founder & CEO","company":"Ad Agency","initials":"SR"}'::jsonb, 0),
  (null, '{"quote":"No fluff. No jargon. Just systems that work.","name":"Siddharth Shrivastava","role":"Marketing Head","company":"RMG Company","initials":"SS"}'::jsonb, 1),
  (null, '{"quote":"He thinks like a strategist and writes like a storyteller. That combination is dangerous in a good way.","name":"Arjun Ravikumar","role":"Agency Partner","company":"TGH","initials":"AR"}'::jsonb, 2),
